import math


def rgap(x, y, w, d, ox, oy, ow, od):
    dx = abs(x - ox) - (w + ow) / 2
    dy = abs(y - oy) - (d + od) / 2
    if dx > 0 and dy > 0:
        return math.sqrt(dx * dx + dy * dy)
    return max(dx, dy)


